/* NeuroFuel data adapter for the existing shared Drops purchase anatomy. */
#neurofuel-purchase132{margin-top:24px;--ink:#1a1a1f}
#neurofuel-purchase132 .nf-flavours132{display:flex;gap:24px;margin-bottom:28px;flex-wrap:wrap}
#neurofuel-purchase132 .options63{margin:0;border:0;padding:0;min-width:0}
#neurofuel-purchase132 .options63 legend{font:700 13px/1.4 Inter,sans-serif;margin-bottom:6px}
#neurofuel-purchase132 .shared-image-options119 button{flex-basis:82px}
#neurofuel-purchase132 .nf-fixed132{font:400 13px/1.6 Inter,sans-serif;margin:0 0 26px;max-width:460px}
#neurofuel-purchase132 .nf-fixed132 strong{display:block;font-weight:700;margin-bottom:4px}
#neurofuel-purchase132 .packs{margin-top:0;margin-bottom:32px}
#neurofuel-purchase132 .purchase-layout{display:grid;grid-template-columns:minmax(0,35fr) minmax(0,65fr);gap:12px;align-items:stretch}
#neurofuel-purchase132 .pack-photo{position:relative;align-self:center;width:100%;aspect-ratio:1;min-height:0;border:1px solid #deded5;border-radius:13px;background:#fff;overflow:hidden}
#neurofuel-purchase132 .pack-render{position:absolute;inset:0}
#neurofuel-purchase132 .pack-render img{position:static;display:block;width:100%;height:100%;object-fit:contain}
#neurofuel-purchase132 .total-discount{position:absolute;z-index:1;display:flex;flex-direction:column;justify-content:center;align-items:center;width:64px;height:64px;top:8px;left:8px;border:1.5px solid #1a1a1f;border-radius:50%;background:var(--accent);color:#1a1a1f;box-shadow:2px 2px 0 #1a1a1f;text-align:center}
#neurofuel-purchase132 .total-discount strong{font-size:20px;line-height:1.1}
#neurofuel-purchase132 .total-discount strong::before{content:'−'}
#neurofuel-purchase132 .total-discount span{font-size:10px;line-height:1.2}
#neurofuel-purchase132 .plan-stack{display:grid;grid-template-rows:1fr 1fr;gap:10px;min-width:0}
#neurofuel-purchase132 .plan{position:relative;display:flex;flex-direction:column;justify-content:center;text-align:left;padding:12px;min-height:92px;border:1px solid var(--brand);border-radius:12px;background:#fff;color:#1a1a1f;box-shadow:none}
#neurofuel-purchase132 .plan[aria-checked=true]{background:var(--brand);color:#fff;border-color:transparent;box-shadow:2px 3px 0 #1a1a1f40}
#neurofuel-purchase132 .plan-label{font:700 14px/1.3 Inter,sans-serif}
#neurofuel-purchase132 .price-row{display:flex;flex-wrap:wrap;gap:5px;align-items:baseline;margin:0}
#neurofuel-purchase132 .each-price{font:700 32px/1.1 Inter,sans-serif;letter-spacing:-1px}
#neurofuel-purchase132 .each{font:400 13px/1.4 Inter,sans-serif}
#neurofuel-purchase132 .nf-contents132{font:400 12px/1.5 Inter,sans-serif;text-align:center;margin:12px 0 0;color:#405a51}
#neurofuel-purchase132 .nf-draft132,#neurofuel-purchase132 .nf-link-note132{font:400 12px/1.5 Inter,sans-serif;background:var(--pale,#edf4ef);border:1px solid #b7c7bf;border-radius:8px;padding:9px 12px;margin:12px 0}
#neurofuel-purchase132 .billing{position:relative;min-height:30px;display:flex;align-items:center;justify-content:center;gap:3px;flex-wrap:wrap;padding:0;margin:16px 0 0;font-size:14px;line-height:1.5;text-align:center}
#neurofuel-purchase132 #billing-subscription{display:inline-flex;align-items:center;justify-content:center;flex-wrap:wrap;gap:4px}
#neurofuel-purchase132 .billing-pill62 select{appearance:none;min-width:0;max-width:100%;border:0;background:transparent;color:inherit;box-shadow:none}
#neurofuel-purchase132 .help{position:relative;padding:0;margin:0;display:inline-flex}
#neurofuel-purchase132 .info{width:24px;height:24px;border:0;background:transparent;color:#405a51;border-radius:0;box-shadow:none}
#neurofuel-purchase132 .help-text{position:absolute;z-index:10;bottom:calc(100% + 9px);right:0;width:min(272px,calc(100vw - 32px));padding:10px 12px;background:#23272a;color:#fff;font:400 12px/1.55 Inter,sans-serif;border-radius:8px;box-shadow:0 6px 20px #0002;text-align:left}
#neurofuel-purchase132 .checkout{display:block;width:100%;border:0;border-radius:6px;background:#000;color:#fff;font:700 17px/1.4 Inter,sans-serif;min-height:54px;margin:0;padding:14px 12px}
#neurofuel-purchase132 .checkout-feedback:empty{display:none}
#neurofuel-purchase132 .checkout-feedback{font-size:12px;text-align:center;margin:10px 0}
#neurofuel-purchase132 .shipping{text-align:center;margin:20px 0;font-size:16px}
@media(max-width:767px){#neurofuel-purchase132 .nf-flavours132{gap:14px;flex-wrap:nowrap}#neurofuel-purchase132 .shared-image-options119 button{flex-basis:72px;font-size:11px}#neurofuel-purchase132 .shared-image-options119 button img{width:64px;height:64px}#neurofuel-purchase132 .plan{padding:8px 9px;min-height:0}#neurofuel-purchase132 .each-price{font-size:28px}#neurofuel-purchase132 .total-discount{width:52px;height:52px}#neurofuel-purchase132 .total-discount strong{font-size:18px}#neurofuel-purchase132 .total-discount span{font-size:9px}#neurofuel-purchase132 .nf-contents132{font-size:11px}}
@media(max-width:360px){#neurofuel-purchase132 .nf-flavours132{gap:10px}#neurofuel-purchase132 .shared-image-options119 button{flex-basis:62px}#neurofuel-purchase132 .shared-image-options119 button img{width:58px;height:58px}#neurofuel-purchase132 .purchase-layout{grid-template-columns:minmax(0,1fr)}#neurofuel-purchase132 .pack-photo{width:180px;justify-self:center}#neurofuel-purchase132 .plan{min-height:92px}#neurofuel-purchase132 .packs .shared-pack-content118 strong{font-size:14px}#neurofuel-purchase132 .packs .shared-pack-content118 small{font-size:10px}}
html:is(.ark-medium-text64,.ark-large-text64) #neurofuel-purchase132 .nf-flavours132{flex-wrap:wrap}
html:is(.ark-medium-text64,.ark-large-text64) #neurofuel-purchase132 .purchase-layout{grid-template-columns:1fr!important}
html:is(.ark-medium-text64,.ark-large-text64) #neurofuel-purchase132 .pack-photo{height:auto!important;width:min(220px,100%)!important;justify-self:center}

(()=>{'use strict';
const root=document.getElementById('neurofuel-purchase132'),data=document.getElementById('neurofuel-data132');if(!root||!data)return;
const config=JSON.parse(data.textContent),state={pack:'single',drops:'Original',melts:'Original',mode:'subscription',weeks:8},money=n=>'£'+(n/100).toFixed(2),q=s=>root.querySelector(s);
const variant=()=>config.variants.find(v=>v.pack===state.pack&&(v.pack==='each'||v.drops===state.drops&&v.melts===state.melts));
const query=new URLSearchParams(location.search),linked=config.variants.find(v=>v.id&&v.id===query.get('variant'));
if(linked){state.pack=linked.pack;state.drops=linked.drops;state.melts=linked.melts;const plan=linked.plans.find(p=>p.id===query.get('selling_plan'));if(plan)state.weeks=plan.weeks;}
else if(query.get('kit')==='one-of-each')state.pack='each';
if(query.has('variant')&&!linked){q('[data-link-note132]').hidden=false;}
const select=q('#billing-frequency');let frequencyKey='';
function render(){
 const v=variant(),plans=v.plans,activePlan=plans.find(p=>p.weeks===state.weeks)||plans[0];state.weeks=activePlan.weeks;
 root.dataset.variant132=v.id||'';root.dataset.sellingPlan132=state.mode==='subscription'?activePlan.id||'':'';root.dataset.pack132=state.pack;root.dataset.proposed132=String(!!v.proposed);
 for(const b of root.querySelectorAll('[data-kit132]')){b.setAttribute('aria-pressed',String(b.dataset.kit132===state.pack));b.setAttribute('aria-checked',String(b.dataset.kit132===state.pack));}
 q('.nf-flavours132').hidden=state.pack==='each';q('.nf-fixed132').hidden=state.pack!=='each';q('[data-draft132]').hidden=!v.proposed;
 for(const b of root.querySelectorAll('[data-flavour132]'))b.setAttribute('aria-pressed',String(state[b.dataset.family132]===b.dataset.flavour132));
 for(const b of root.querySelectorAll('[data-kit132]')){const option=config.variants.find(x=>x.pack===b.dataset.kit132&&(x.pack==='each'||x.drops===state.drops&&x.melts===state.melts)),plan=option.plans.find(p=>p.weeks===state.weeks)||option.plans[0],price=state.mode==='once'?option.price:Math.round(option.price*(1-plan.percent/100));b.querySelector('.discount').textContent=Math.round(100*(1-price/option.compare))+'% OFF';}
 const image=q('.pack-render img');if(image.getAttribute('src')!==v.image)image.src=v.image;image.alt=v.contents;q('#pack-caption').textContent=v.contents;q('[data-contents132]').textContent=v.contents;
 const sub=Math.round(v.price*(1-activePlan.percent/100)),paid=state.mode==='subscription'?sub:v.price;
 q('.total-discount strong').textContent=Math.round(100*(1-paid/v.compare))+'%';q('.plan-badge').textContent=activePlan.percent+'% OFF & Cancel Anytime';
 for(const b of root.querySelectorAll('[data-plan]')){const mode=b.dataset.plan,total=mode==='once'?v.price:sub;b.setAttribute('aria-checked',String(mode===state.mode));b.querySelector('.each-price').textContent=money(Math.round(total/v.kits));b.querySelector('.each').textContent=v.proposed?'per set':'per kit';b.querySelector('.total-price').textContent=money(total);b.querySelector('s').textContent=money(v.compare);}
 const key=plans.map(p=>p.weeks).join('|');if(key!==frequencyKey){select.replaceChildren(...plans.map(p=>{const o=document.createElement('option');o.value=String(p.weeks);o.textContent='Billed every '+p.weeks+' weeks';return o;}));frequencyKey=key;}
 for(const option of select.querySelectorAll('option')){if(option.value===String(state.weeks))option.setAttribute('selected','');else option.removeAttribute('selected');}
 const mirror=select.closest('.native-select64')?.querySelector('.native-select-label64');if(mirror)mirror.textContent='Billed every '+state.weeks+' weeks';
 q('#billing-subscription').hidden=state.mode==='once';q('#billing-once').hidden=state.mode!=='once';q('.help').hidden=state.mode==='once';
 q('#subscription-help').hidden=true;q('.info').setAttribute('aria-expanded','false');q('#checkout-feedback').textContent='';
 q('[data-summary132]').textContent=v.contents+'. '+(state.mode==='subscription'?'Subscription, every '+state.weeks+' weeks.':'One-time purchase.')+' Total '+money(paid)+(v.proposed?' · Draft pricing.':'');
}
root.addEventListener('click',e=>{const tier=e.target.closest('[data-kit132]'),flavour=e.target.closest('[data-flavour132]'),plan=e.target.closest('[data-plan]');if(tier){state.pack=tier.dataset.kit132;render();}else if(flavour){state[flavour.dataset.family132]=flavour.dataset.flavour132;render();}else if(plan){state.mode=plan.dataset.plan;render();}});
for(const group of root.querySelectorAll('[role=radiogroup]'))group.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;const buttons=[...group.querySelectorAll('[role=radio]')],index=buttons.indexOf(e.target);if(index<0)return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(['ArrowRight','ArrowDown'].includes(e.key)?1:buttons.length-1))%buttons.length;buttons[next].click();buttons[next].focus();});
select.addEventListener('change',()=>{state.weeks=Number(select.value);render();});
q('.info').addEventListener('click',()=>{const panel=q('#subscription-help'),button=q('.info');panel.hidden=!panel.hidden;button.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden){panel.style.transform='';const box=panel.getBoundingClientRect();panel.style.transform='translateX('+Math.max(8-box.left,Math.min(0,innerWidth-8-box.right))+'px)';}});
q('#checkout').addEventListener('click',()=>{q('#checkout-feedback').textContent='Design preview only. No order or payment is created.';});render();
})();
